begin;
with j as (select * from jsonb_to_recordset($law7d0019$[{"code_id":"APK_RF","article_number":"34","version_date":"2002-07-24","article_text":"1) дела об оспаривании нормативных правовых актов федеральных органов исполнительной власти в сфере патентных прав и прав на селекционные достижения, права на топологии интегральных микросхем, права на секреты производства (ноу-хау), права на средства индивидуализации юридических лиц, товаров, работ, услуг и предприятий, права использования результатов интеллектуальной деятельности в составе единой технологии; (В редакции Федерального закона от 28.06.2014 № 186-ФЗ)\n\n11) дела об оспаривании актов федеральных органов исполнительной власти в сфере патентных прав и прав на селекционные достижения, права на топологии интегральных микросхем, права на секреты производства (ноу-хау), права на средства индивидуализации юридических лиц, товаров, работ, услуг и предприятий, права использования результатов интеллектуальной деятельности в составе единой технологии, содержащих разъяснения законодательства и обладающих нормативными свойствами; (Дополнение пунктом - Федеральный закон от 15.02.2016 № 18-ФЗ)\n\n2) дела по спорам о предоставлении или прекращении правовой охраны результатов интеллектуальной деятельности и приравненных к ним средств индивидуализации юридических лиц, товаров, работ, услуг и предприятий (за исключением объектов авторских и смежных прав, топологий интегральных микросхем), в том числе:\n\nоб оспаривании ненормативных правовых актов, решений и действий (бездействия) фе\n\nдерального органа исполнительной власти по интеллектуальной собственности, федерального органа исполнительной власти по селекционным достижениям и их должностных лиц, а также органов, уполномоченных Правительством Российской Федерации рассматривать заявки на выдачу патента на секретные изобретения;\n\nоб оспаривании решений федерального антимонопольного органа о признании недобросовестной конкуренцией действий, связанных с приобретением исключительного права на средства индивидуализации юридического лица, товаров, работ, услуг и предприятий;\n\nоб установлении патентообладателя;\n\nо признании недействительными патента на изобретение, полезную модель, промышленный образец или селекционное достижение, решения о предоставлении правовой охраны товарному знаку, наименованию места происхождения товара и о предоставлении исключительного права на такое наименование, если федеральным законом не предусмотрен иной порядок их признания недействительными;\n\nо досрочном прекращении правовой охраны товарного знака вследствие его неиспользования.\n\n(Дополнение частью - Федеральный закон от 08.12.2011 № 422-ФЗ)","article_title":"Статья 34. Подсудность дел арбитражным судам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"caacd619d7165335d3aed56fea6fc8b76e630261f46715d4c9d8a0319b4b899f"},{"code_id":"APK_RF","article_number":"35","version_date":"2002-07-24","article_text":"Иск предъявляется в арбитражный суд субъекта Российской Федерации по адресу или месту жительства ответчика.\n\n(Статья в редакции Федерального закона от 28.11.2018 № 451-ФЗ)","article_title":"Статья 35. Предъявление иска по адресу или месту жительства ответчика","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"13148b7bc560bedf116f207f8bfa3e1a241c099a903b642576dcbdaee8f4855c"},{"code_id":"APK_RF","article_number":"36","version_date":"2002-07-24","article_text":"1. Иск к ответчику, место нахождения или место жительства которого неизвестно, может быть предъявлен в арбитражный суд по месту нахождения его имущества либо по его последнему известному месту нахождения или месту жительства в Российской Федерации.","article_title":"Статья 36. Подсудность по выбору истца","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"919397595530c13ea20ea647189974b9aeed7c81c0a00b87a2f4cff2b7325369"},{"code_id":"APK_RF","article_number":"37","version_date":"2002-07-24","article_text":"Подсудность, установленная статьями 35 и 36 настоящего Кодекса, может быть изменена по соглашению сторон до принятия арбитражным судом заявления к своему производству.","article_title":"Статья 37. Договорная подсудность","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3c69d60d508a7aae212bac1190883c2c7725ceb8b926caafffcce7dea8d459cf"},{"code_id":"APK_RF","article_number":"38","version_date":"2002-07-24","article_text":"1. Иски о правах на недвижимое имущество предъявляются в арбитражный суд по месту нахождения этого имущества.\n\n2. Иски о правах на морские и воздушные суда, суда внутреннего плавания, космические объекты предъявляются в арбитражный суд по месту их государственной регистрации.\n\n3. Иск к перевозчику, вытекающий из договора перевозки грузов, пассажиров и их багажа, в том числе в случае, если перевозчик является одним из ответчиков, предъявляется в арбитражный суд по месту нахождения перевозчика.\n\nЗаявление об оспаривании решения Федеральной службы судебных приставов, принятого в автоматическом режиме, подается в арбитражный суд по месту совершения исполнительных действий или применения мер принудительного исполнения либо по месту ведения исполнительного производства, по которому принято оспариваемое решение. (Дополнение абзацем - Федеральный закон от 21.12.2021 № 417-ФЗ)\n\nЗаявления по спорам между российскими организациями, осуществляющими деятельность или имеющими имущество на территории иностранного государства и не имеющими государственной регистрации на территории Российской Федерации, подаются в Арбитражный суд Московской области.","article_title":"Статья 38. Исключительная подсудность","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4898d097a6464cccdc4ee6ead6a1bac9aa1c64a76acb276ffc0f864e7c76789f"},{"code_id":"APK_RF","article_number":"39","version_date":"2002-07-24","article_text":"1. Дело, принятое арбитражным судом к своему производству с соблюдением правил подсудности, должно быть рассмотрено им по существу, хотя бы в дальнейшем оно стало подсудным другому суду.\n\n2. Арбитражный суд передает дело на рассмотрение другого арбитражного суда того же уровня в случае, если:\n\n1) ответчик, адрес или место жительства которого не было известно ранее, заявит ходатайство о передаче дела в арбитражный суд по его адресу или месту жительства;\n\n2) обе стороны заявили ходатайство о рассмотрении дела по месту нахождения большинства доказательств;\n\n3) при рассмотрении дела в суде выяснилось, что оно было принято к производству с нарушением правил подсудности;\n\n4) при рассмотрении дела в суде было установлено, что лицом, участвующим в деле, является тот же арбитражный суд;\n\n5) после отвода одного или нескольких судей либо по другим причинам невозможно сформировать состав суда для рассмотрения данного дела.\n\n3. В предусмотренном пунктом 4 части 2 настоящей статьи случае арбитражный суд передает дело на рассмотрение другого определяемого в соответствии с частью 31 статьи 38 настоящего Кодекса арбитражного суда.\n\n4. Если при рассмотрении дела в арбитражном суде выяснилось, что оно подлежит рассмотрению судом общей юрисдикции, арбитражный суд передает дело в верховный суд республики, краевой, областной суд, суд города федерального значения, суд автономной области или суд автономного округа того же субъекта Российской Федерации для направления его в суд общей юрисдикции, к подсудности которого оно отнесено законом.\n\n5. По результатам рассмотрения арбитражным судом вопроса о передаче дела на рассмотрение другого арбитражного суда или суда общей юрисдикции выносится определение, которое может быть обжаловано в арбитражный суд апелляционной инстанции в десятидневный срок со дня его вынесения. Жалоба на это определение рассматривается без вызова сторон в пятидневный срок со дня ее поступления в суд. Дело и определение направляются в арбитражный суд или суд общей юрисдикции по истечении срока, предусмотренного для обжалования этого определения, а в случае подачи жалобы - после принятия постановления суда об оставлении жалобы без удовлетворения.\n\n6. Дело, направленное из одного арбитражного суда в другой арбитражный суд или из арбитражного суда в суд общей юрисдикции, должно быть принято к рассмотрению судом, в который оно направлено. Споры о подсудности между судами в Российской Федерации не допускаются.\n\n(Статья в редакции Федерального закона от 28.11.2018 № 451-ФЗ)","article_title":"Статья 39. Передача дела, принятого арбитражным судом к своему производству, из одного суда в другой суд","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f99f62f7f96a2e4d4d47eeb3d9b002d900d3fa51a7182274c3444086c8b90351"},{"code_id":"APK_RF","article_number":"4","version_date":"2002-07-24","article_text":"искового заявления - по экономическим спорам и иным делам, возникающим из гражданских правоотношений;\n\nзаявления - по делам, возникающим из административных и иных публичных правоотношений, по делам о несостоятельности (банкротстве), по делам особого производства, по делам приказного производства и в иных случаях, предусмотренных настоящим Кодексом; (В редакции федеральных законов от 28.06.2014 № 186-ФЗ; от 02.03.2016 № 47-ФЗ)\n\nжалобы - при обращении в арбитражный суд апелляционной и кассационной инстанций, а также в иных случаях, предусмотренных настоящим Кодексом и иными федеральными законами;\n\nпредставления - при обращении Генерального прокурора Российской Федерации и его заместителей о пересмотре судебных актов в порядке надзора.\n\nИные споры, возникающие из гражданских правоотношений, передаются на разрешение арбитражного суда после соблюдения досудебного порядка урегулирования спора только в том случае, если такой порядок установлен федеральным законом или договором.\n\nЭкономические споры, возникающие из административных и иных публичных правоотношений, могут быть переданы на разрешение арбитражного суда после соблюдения досудебного порядка урегулирования спора в случае, если такой порядок установлен федеральным законом.\n\nСоблюдения досудебного порядка урегулирования спора не требуется по делам об установлении фактов, имеющих юридическое значение, делам о присуждении компенсации за нарушение права на судопроизводство в разумный срок или права на исполнение судебного акта в разумный срок, делам о несостоятельности (банкротстве), делам по корпоративным спорам, делам о защите прав и законных интересов группы лиц, делам приказного производства, делам, связанным с выполнением арбитражными судами функций содействия и контроля в отношении третейских судов, делам о признании и приведении в исполнение решений иностранных судов и иностранных арбитражных решений, а также, если иное не предусмотрено законом, при обращении в арбитражный суд прокурора, государственных органов, органов местного самоуправления и иных органов в защиту публичных интересов, прав и законных интересов организаций и граждан в сфере предпринимательской и иной экономической деятельности (статьи 52, 53 настоящего Кодекса).\n\n(Часть в редакции Федерального закона от 01.07.2017 № 147-ФЗ)\n\nИсковое заявление, заявление, жалоба, представление и иные документы в электронном виде могут быть поданы в суд посредством федеральной государственной информационной системы \"Единый портал государственных и муниципальных услуг (функций)\" (далее - единый портал государственных и муниципальных услуг), либо информационной системы, определенной Верховным Судом Российской Федерации, Судебным департаментом при Верховном Суде Российской Федерации, либо систем электронного документооборота участников арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия.\n\nИсковое заявление, заявление, жалоба, представление и иные документы, которые подаются посредством единого портала государственных и муниципальных услуг, информационной системы, определенной Верховным Судом Российской Федерации, Судебным департаментом при Верховном Суде Российской Федерации, могут быть подписаны простой электронной подписью в соответствии с законодательством Российской Федерации и порядком, определяемым Верховным Судом Российской Федерации, Судебным департаментом при Верховном Суде Российской Федерации, если настоящим Кодексом не установлено, что указанные документы должны быть подписаны усиленной квалифицированной электронной подписью.\n\nИсковое заявление, заявление, жалоба, представление и иные документы, которые подаются посредством систем электронного документооборота участников арбитражного процесса, должны быть подписаны усиленной квалифицированной электронной подписью.\n\n(Дополнение частью - Федеральный закон от 23.06.2016 № 220-ФЗ) (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)","article_title":"Статья 4. Право на обращение в арбитражный суд","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a65021ab06b57d00c571192fea38670f20c8e2cf3e24a42ba5bd4a9914e8f581"},{"code_id":"APK_RF","article_number":"40","version_date":"2002-07-24","article_text":"Лицами, участвующими в деле, являются:\n\nзаявители и заинтересованные лица - по делам особого производства, по делам о несостоятельности (банкротстве) и в иных предусмотренных настоящим Кодексом случаях;\n\nтретьи лица;\n\nпрокурор, государственные органы, органы местного самоуправления, иные органы и организации, граждане, обратившиеся в арбитражный суд в случаях, предусмотренных настоящим Кодексом. (В редакции Федерального закона от 19.07.2009 № 205-ФЗ)","article_title":"Статья 40. Состав лиц, участвующих в деле","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"64fa30b5b1e6feb7c02389549ee5b13bac9c6641946c1838e167fe0e571cdc7f"},{"code_id":"APK_RF","article_number":"41","version_date":"2002-07-24","article_text":"Лица, участвующие в деле, также вправе представлять в арбитражный суд документы в электронном виде, в том числе в форме электронного документа, подписанного электронной подписью в порядке, установленном законодательством Российской Федерации. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 228-ФЗ) (В редакции федеральных законов от 23.06.2016 № 220-ФЗ, от 30.12.2021 № 440-ФЗ)\n\nЗлоупотребление процессуальными правами лицами, участвующими в деле, влечет за собой для этих лиц предусмотренные настоящим Кодексом неблагоприятные последствия.\n\nНеисполнение процессуальных обязанностей лицами, участвующими в деле, влечет за собой для этих лиц предусмотренные настоящим Кодексом последствия.","article_title":"Статья 41. Права и обязанности лиц, участвующих в деле","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"49bd89eb81b9a082322635f49f9a59dc2acb4a27c3771b34063a17e4022e3585"},{"code_id":"APK_RF","article_number":"42","version_date":"2002-07-24","article_text":"Лица, не участвовавшие в деле, о правах и об обязанностях которых арбитражный суд принял судебный акт, вправе обжаловать этот судебный акт, а также оспорить его в порядке надзора по правилам, установленным настоящим Кодексом. Такие лица пользуются правами и несут обязанности лиц, участвующих в деле.","article_title":"Статья 42. Права лиц, не участвовавших в деле, о правах и об обязанностях которых арбитражный суд принял судебный акт","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e81b7fb5243fed62fd7371f8e6177d5e7d14f13d94b5aaaf138671a04e0cc448"},{"code_id":"APK_RF","article_number":"43","version_date":"2002-07-24","article_text":"1. Способность иметь процессуальные права и нести процессуальные обязанности (процессуальная правоспособность) признается в равной мере за всеми организациями и гражданами, обладающими согласно федеральному закону правом на судебную защиту в арбитражном суде своих прав и законных интересов.\n\n2. Способность своими действиями осуществлять процессуальные права и исполнять процессуальные обязанности (процессуальная дееспособность) принадлежит в арбитражном суде организациям и гражданам.\n\n3. Права и законные интересы недееспособных граждан защищают в арбитражном процессе их законные представители - родители, усыновители, опекуны или попечители.","article_title":"Статья 43. Процессуальная правоспособность и процессуальная дееспособность","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a1f8241cf1e96cced45d7d3fc28a7fbf594c6c35df1b54492078b99d4fb9d767"},{"code_id":"APK_RF","article_number":"44","version_date":"2002-07-24","article_text":"1. Сторонами в арбитражном процессе являются истец и ответчик.\n\n2. Истцами являются организации и граждане, предъявившие иск в защиту своих прав и законных интересов.\n\n3. Ответчиками являются организации и граждане, к которым предъявлен иск.\n\n4. Стороны пользуются равными процессуальными правами.","article_title":"Статья 44. Стороны","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1d274f05d4e56aba73b1a30e128cfbe26c36f63f49c11da04039ed3195cd42b1"},{"code_id":"APK_RF","article_number":"45","version_date":"2002-07-24","article_text":"1. Заявителями являются организации и граждане, обращающиеся в арбитражный суд с заявлениями в предусмотренных настоящим Кодексом и иным федеральным законом случаях и вступающие в арбитражный процесс по этим заявлениям.\n\n2. Заявители пользуются процессуальными правами и несут процессуальные обязанности стороны, если иное не предусмотрено настоящим Кодексом.","article_title":"Статья 45. Заявители","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3a80d08ed24943cd2f807c8b46252f44e840e03e12757a8db9b3476d5adb9f95"},{"code_id":"APK_RF","article_number":"46","version_date":"2002-07-24","article_text":"1. Иск может быть предъявлен в арбитражный суд совместно несколькими истцами или к нескольким ответчикам (процессуальное соучастие).\n\n2. Процессуальное соучастие допускается, если:\n\n1) предметом спора являются общие права и (или) обязанности нескольких истцов либо ответчиков;\n\n2) права и (или) обязанности нескольких истцов либо ответчиков имеют одно основание;\n\n3) предметом спора являются однородные права и обязанности.\n\n3. Каждый из истцов или ответчиков по отношению к другой стороне выступает в процессе самостоятельно. Соучастники могут поручить ведение дела одному или нескольким из них.\n\n4. Соистцы могут вступить в дело до принятия судебного акта, которым заканчивается рассмотрение дела по существу в арбитражном суде первой инстанции.\n\n5. При невозможности рассмотрения дела без участия другого лица в качестве ответчика арбитражный суд первой инстанции привлекает его к участию в деле как соответчика по ходатайству сторон или с согласия истца.\n\n6. В случае, если федеральным законом предусмотрено обязательное участие в деле другого лица в качестве ответчика, а также по делам, вытекающим из административных и иных публичных правоотношений, арбитражный суд первой инстанции по своей инициативе привлекает его к участию в деле в качестве соответчика.\n\n7. О вступлении в дело соистца, о привлечении соответчика или об отказе в этом выносится определение. Определение об отказе в удовлетворении ходатайства о вступлении в дело соистца, о привлечении соответчика может быть обжаловано лицом, подавшим соответствующее ходатайство, в срок, не превышающий десяти дней со дня его вынесения, в арбитражный суд апелляционной инстанции.\n\n8. После вступления в дело соистца, привлечения к участию в деле соответчика рассмотрение дела производится с самого начала.\n\n(Статья в редакции Федерального закона от 19.07.2009 № 205-ФЗ)","article_title":"Статья 46. Участие в деле нескольких истцов или ответчиков","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5b822d5fb1478783a29a3f21088a637ac98700bbaefb88a60339096eecdd6092"},{"code_id":"APK_RF","article_number":"47","version_date":"2002-07-24","article_text":"1. В случае, если при подготовке дела к судебному разбирательству или во время судебного разбирательства в суде первой инстанции будет установлено, что иск предъявлен не к тому лицу, которое должно отвечать по иску, арбитражный суд может по ходатайству или с согласия истца допустить замену ненадлежащего ответчика надлежащим.\n\n2. Если истец не согласен на замену ответчика другим лицом, суд может с согласия истца привлечь это лицо в качестве второго ответчика.\n\n3. После замены ненадлежащего ответчика или вступления в дело второго ответчика рассмотрение дела производится с самого начала.\n\n4. О замене ненадлежащего ответчика надлежащим или привлечении надлежащего ответчика в качестве второго ответчика арбитражный суд выносит определение.\n\nЕсли истец не согласен на замену ответчика другим лицом или на привлечение этого лица в качестве второго ответчика, арбитражный суд рассматривает дело по предъявленному иску.","article_title":"Статья 47. Замена ненадлежащего ответчика","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1575a0aae753755e5bfe20e719dd59b30378abe56baae744a2ac8b4ac8e5c897"},{"code_id":"APK_RF","article_number":"48","version_date":"2002-07-24","article_text":"1. В случаях выбытия одной из сторон в спорном или установленном судебным актом арбитражного суда правоотношении (реорганизация юридического лица, уступка требования, перевод долга, смерть гражданина и другие случаи перемены лиц в обязательствах) арбитражный суд производит замену этой стороны ее правопреемником и указывает на это в судебном акте. Правопреемство возможно на любой стадии арбитражного процесса.","article_title":"Статья 48. Процессуальное правопреемство","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"438381279db3d48d55b103b5fddad7c878f6039d2298199a7974d1d6caf94dac"},{"code_id":"APK_RF","article_number":"49","version_date":"2002-07-24","article_text":"1. Истец вправе при рассмотрении дела в арбитражном суде первой инстанции до принятия судебного акта, которым заканчивается рассмотрение дела по существу, изменить основание или предмет иска, увеличить или уменьшить размер исковых требований.","article_title":"Статья 49. Изменение основания или предмета иска, изменение размера исковых требований, отказ от иска, признание иска, мировое соглашение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0f16466a27f0e600a06ab91aebda3fcd7a628b070a2347fcaef718e17eb4b4a6"},{"code_id":"APK_RF","article_number":"5","version_date":"2002-07-24","article_text":"1. При осуществлении правосудия судьи арбитражных судов независимы, подчиняются только Конституции Российской Федерации и федеральному закону.\n\n2. Какое-либо постороннее воздействие на судей арбитражных судов, вмешательство в их деятельность государственных органов, органов местного самоуправления, иных органов, организаций, должностных лиц или граждан запрещаются и влекут за собой ответственность, установленную законом.\n\n3. Гарантии независимости судей арбитражных судов устанавливаются Конституцией Российской Федерации и федеральным законом.","article_title":"Статья 5. Независимость судей арбитражных судов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6b8e1d9d6c8655107493894fdcb95636908513b9c1165103382b8e0441ad2708"},{"code_id":"APK_RF","article_number":"50","version_date":"2002-07-24","article_text":"1. Третьи лица, заявляющие самостоятельные требования относительно предмета спора, могут вступить в дело до принятия решения арбитражным судом первой инстанции.\n\n2. Третьи лица, заявляющие самостоятельные требования относительно предмета спора, пользуются правами и несут обязанности истца, за исключением обязанности соблюдения претензионного или иного досудебного порядка урегулирования спора, если это предусмотрено федеральным законом для данной категории споров или договором.\n\n3. В случае, если третье лицо, заявляющее самостоятельные требования относительно предмета спора, вступило в дело после начала судебного разбирательства, рассмотрение дела в первой инстанции арбитражного суда производится с самого начала.","article_title":"Статья 50. Третьи лица, заявляющие самостоятельные требования относительно предмета спора","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c40715c1fa7aea7cece80e992bed018f4ee82204088c0d4c2b15c933e955f030"},{"code_id":"APK_RF","article_number":"51","version_date":"2002-07-24","article_text":"1. Третьи лица, не заявляющие самостоятельных требований относительно предмета спора, могут вступить в дело на стороне истца или ответчика до принятия судебного акта, которым заканчивается рассмотрение дела в первой инстанции арбитражного суда, если этот судебный акт может повлиять на их права или обязанности по отношению к одной из сторон. Они могут быть привлечены к участию в деле также по ходатайству стороны или по инициативе суда.","article_title":"Статья 51. Третьи лица, не заявляющие самостоятельных требований относительно предмета спора","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"925822071b7f197dc86659839fe366d965b32e310ecc887dc6ba8f76cf7841d6"},{"code_id":"APK_RF","article_number":"52","version_date":"2002-07-24","article_text":"1. Прокурор вправе обратиться в арбитражный суд:\n\nс заявлениями об оспаривании нормативных правовых актов, ненормативных правовых актов органов государственной власти Российской Федерации, органов государственной власти субъектов Российской Федерации, органов местного самоуправления, затрагивающих права и законные интересы организаций и граждан в сфере предпринимательской и иной экономической деятельности;\n\nс иском о признании недействительными сделок, совершенных органами государственной власти Российской Федерации, органами государственной власти субъектов Российской Федерации, органами местного самоуправления, государственными и муниципальными унитарными предприятиями, государственными учреждениями, а также юридическими лицами, в уставном капитале (фонде) которых есть доля участия Российской Федерации, доля участия субъектов Российской Федерации, доля участия муниципальных образований;\n\nс иском о применении последствий недействительности ничтожной сделки, совершенной органами государственной власти Российской Федерации, органами государственной власти субъектов Российской Федерации, органами местного самоуправления, государственными и муниципальными унитарными предприятиями, государственными учреждениями, а также юридическими лицами, в уставном капитале (фонде) которых есть доля участия Российской Федерации, доля участия субъектов Российской Федерации, доля участия муниципальных образований;\n\nс иском об истребовании государственного и муниципального имущества из чужого незаконного владения; (Дополнение абзацем - Федеральный закон от 28.06.2014 № 186-ФЗ)\n\nс иском о признании недействительными сделок, совершенных с нарушением требований законодательства в сфере государственного оборонного заказа в том числе государственными заказчиками государственного оборонного заказа, головными исполнителями поставок продукции по государственному оборонному заказу и исполнителями, участвующими в поставках продукции по государственному оборонному заказу, не указанными в абзацах третьем и четвертом настоящей части, и о применении последствий недействительности таких сделок; (Дополнение абзацем - Федеральный закон от 01.07.2021 № 282-ФЗ)\n\nс иском о признании недействительными сделок, совершенных с нарушением требований законодательства о контрактной системе в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд в том числе заказчиками, поставщиками (подрядчиками, исполнителями), субподрядчиками, соисполнителями, участвующими в обеспечении государственных и муниципальных нужд, не указанными в абзацах третьем и четвертом настоящей части, и о применении последствий недействительности таких сделок; (Дополнение абзацем - Федеральный закон от 01.07.2021 № 282-ФЗ)\n\nс иском о возмещении ущерба, причиненного Российской Федерации, субъектам Российской Федерации и муниципальным образованиям в результате нарушения законодательства в сфере государственного оборонного заказа, а также законодательства о контрактной системе в сфере закупок товаров, работ, услуг для обеспечения государственных и муниципальных нужд; (Дополнение абзацем - Федеральный закон от 01.07.2021 № 282-ФЗ)\n\nс иском о признании недействительными сделок, совершенных в целях уклонения от исполнения обязанностей и процедур, предусмотренных законодательством о противодействии легализации (отмыванию) доходов, полученных преступным путем, и финансированию терроризма, законодательством о налогах и сборах, валютным законодательством Российской Федерации, правом Евразийского экономического союза в сфере таможенных правоотношений и законодательством Российской Федерации о таможенном регулировании, и о применении последствий недействительности таких сделок; (Дополнение абзацем - Федеральный закон от 07.10.2022 № 387-ФЗ)\n\nс иском о признании недействительными сделок, совершенных с нарушением законодательства, устанавливающего специальные экономические меры, меры воздействия (противодействия) на недружественные действия иностранных государств, и о применении последствий недействительности таких сделок. (Дополнение абзацем - Федеральный закон от 07.10.2022 № 387-ФЗ)\n\nпо категориям дел, указанным в части 1 настоящей статьи;\n\nпри рассмотрении заявлений о выдаче исполнительного листа на принудительное исполнение решения третейского суда;\n\nпри рассмотрении заявлений о признании и приведении в исполнение решений иностранных судов и иностранных арбитражных решений;\n\nв случае выявления обстоятельств, свидетельствующих о том, что являющийся предметом судебного разбирательства спор инициирован в целях уклонения от исполнения обязанностей и процедур, предусмотренных законодательством о противодействии легализации (отмыванию) доходов, полученных преступным путем, и финансированию терроризма, законодательством о налогах и сборах, валютным законодательством Российской Федерации, правом Евразийского экономического союза в сфере таможенных правоотношений и законодательством Российской Федерации о таможенном регулировании, а также законодательством, устанавливающим специальные экономические меры, меры воздействия (противодействия) на недружественные действия иностранных государств, и (или) возник из мнимой или притворной сделки, совершенной в указанных целях;\n\nв случае, если в рамках дела о несостоятельности (банкротстве) затрагиваются жилищные права граждан, в том числе несовершеннолетних.\n\n(Часть в редакции Федерального закона от 07.10.2022 № 387-ФЗ)","article_title":"Статья 52. Участие в деле прокурора","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8b3d8d8b38c6a10e73e85254af8e788b150964aba51ef20026f6ecbe6f39b9f8"}]$law7d0019$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
